BEGIN;

CREATE TABLE IF NOT EXISTS skolenza."PolicyVersionLeaveType" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "PolicyVersionId" bigint NOT NULL REFERENCES skolenza."PolicyVersion"("Id") ON DELETE CASCADE,
    "LeaveTypeId" integer NOT NULL REFERENCES skolenza."LeaveType"("Id") ON DELETE RESTRICT,
    "IsActive" boolean NOT NULL DEFAULT true,
    "AddedById" bigint NOT NULL,
    "AddedDateTime" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "UQ_PolicyVersionLeaveType_Version_LeaveType" UNIQUE ("PolicyVersionId", "LeaveTypeId")
);

CREATE TABLE IF NOT EXISTS skolenza."PolicyRuleLeaveType" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "PolicyRuleId" bigint NOT NULL REFERENCES skolenza."PolicyRule"("Id") ON DELETE CASCADE,
    "LeaveTypeId" integer NOT NULL REFERENCES skolenza."LeaveType"("Id") ON DELETE RESTRICT,
    CONSTRAINT "UQ_PolicyRuleLeaveType_Rule_LeaveType" UNIQUE ("PolicyRuleId", "LeaveTypeId")
);

CREATE TABLE IF NOT EXISTS skolenza."PolicyApplicabilityLeaveType" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "InstitutionId" bigint NOT NULL,
    "PolicyApplicabilityId" bigint NOT NULL REFERENCES skolenza."PolicyApplicability"("Id") ON DELETE CASCADE,
    "LeaveTypeId" integer NOT NULL REFERENCES skolenza."LeaveType"("Id") ON DELETE RESTRICT,
    CONSTRAINT "UQ_PolicyApplicabilityLeaveType_Scope_LeaveType" UNIQUE ("PolicyApplicabilityId", "LeaveTypeId")
);

CREATE INDEX IF NOT EXISTS "IX_PolicyVersionLeaveType_Institution_LeaveType"
    ON skolenza."PolicyVersionLeaveType" ("InstitutionId", "LeaveTypeId");
CREATE INDEX IF NOT EXISTS "IX_PolicyRuleLeaveType_Institution_LeaveType"
    ON skolenza."PolicyRuleLeaveType" ("InstitutionId", "LeaveTypeId");
CREATE INDEX IF NOT EXISTS "IX_PolicyApplicabilityLeaveType_Institution_LeaveType"
    ON skolenza."PolicyApplicabilityLeaveType" ("InstitutionId", "LeaveTypeId");

INSERT INTO skolenza."LeaveType"
    ("InstitutionId", "LeaveName", "Description", "IsActive", "AddedById", "AddedDateTime", "IsSoftDeleted")
SELECT institution."Id", seed."LeaveName", seed."Description", true, admin."StaffMemberId", CURRENT_TIMESTAMP, false
FROM skolenza."Institution" institution
CROSS JOIN (VALUES
    ('Casual Leave', 'Short personal leave; normally lapses at the end of the policy year.'),
    ('Earned Leave', 'Service-earned leave that can accrue periodically and may carry forward.'),
    ('Sick Leave', 'Health-related leave governed by eligibility and evidence rules.'),
    ('Maternity Leave', 'Statutory maternity leave governed by staffMember eligibility.'),
    ('Paternity Leave', 'Paternity leave governed by staffMember eligibility.'),
    ('Menstrual Leave', 'Health-related leave for eligible staffMembers experiencing menstrual health needs, governed by institution policy and applicable law.'),
    ('Bereavement Leave', 'Compassionate leave following the death of an eligible family member or dependent.'),
    ('Birthday Leave', 'Optional paid leave granted on or around an eligible staffMember''s birthday under institution policy.')
) AS seed("LeaveName", "Description")
CROSS JOIN LATERAL (
    SELECT staffMember."Id" AS "StaffMemberId"
    FROM skolenza."StaffMember" staffMember
    WHERE staffMember."InstitutionId" = institution."Id"
    ORDER BY staffMember."Id"
    LIMIT 1
) admin
WHERE institution."IsActive" = true
  AND NOT EXISTS (
      SELECT 1 FROM skolenza."LeaveType" existing
      WHERE existing."InstitutionId" = institution."Id"
        AND lower(existing."LeaveName") = lower(seed."LeaveName")
        AND existing."IsSoftDeleted" IS NOT TRUE
  );

COMMIT;
